import React, { useEffect, useState } from "react";
import "./MyProfilePage.css";
import { useParams } from "react-router-dom";
import {
  selectSectionContent,
  setActiveSection,
} from "../../store/slices/SectionSlice/SectionSlice";
import { useDispatch, useSelector } from "react-redux";


function MyProfilePage() {
  const { id } = useParams(); 
  // const [profile, setProfile] = useState(null);
  
  // useEffect(() => {
  //   const fetchProfile = async () => {
  //     try {
  //       const token = localStorage.getItem("token");
  //       const res = await fetch(`http://localhost:8000/api/users/${id}`, {
  //         headers: {
  //           "Content-Type": "application/json",
  //           Authorization: `Bearer ${token}`,
  //         },
  //       });
  //       const data = await res.json();
  //       setProfile(data);
  //     } catch (err) {
  //       console.error("Error fetching profile:", err);
  //     }
  //   };
  
  //   fetchProfile();
  // }, [id]);
const profile = JSON.parse(localStorage.getItem("userProfile"))
console.log(profile);


  const dispatch = useDispatch();
  const sectionContent = useSelector(selectSectionContent);

  
  //  const FindImage = singleData[0]?.Photo?.map((el) => {
  //  return el.key ? el.url : ""
    
  // });
  const goToSection = (section) => {
    dispatch(setActiveSection(section));
    navigate(`/profile/${id}/${section.toLowerCase()}`);
  };
  

  return (
    <div className="MyProfilePage">
     {
            <div key={profile?.id}> 
              <div style={{ marginBottom: "20px" }}>
            <img
              src={profile?.image}
              style={{
                backgroundColor: "#ccc",
                width: "100px",
                height: "100px",
                borderRadius: "50%",
                margin: "0 auto",
              }}
              alt=""
            ></img>
            <h2>
              {profile?.first_name} {profile?.last_name}
            </h2>
            <p>Friends: 330</p>
          </div>
    
          <nav className="nav-buttons" style={{ marginBottom: "20px" }}>
            <button
              onClick={() => dispatch(setActiveSection("Info"))}
              className="nav-button"
            >
              Info
            </button>
            <button
              onClick={() => goToSection("Friends")}
              className="nav-button"
            >
              Friends
            </button>
            <button
              onClick={() => dispatch(setActiveSection("Photo"))}
              className="nav-button"
            >
              Photo
            </button>
            
          </nav>
    
          <div className="section-content" >
          <Outlet />
          </div>
            </div>

     }
    </div>
  );
}

export default MyProfilePage;
